let SelectedDragable=0,CurrVarName='',
GlobalSelection =null,
CurrDragAnzahlablage =null,
CurrDragIsUnEndlich='',
CurrKartZuShau='',
CurrKartMitKarte='',
CurrZusaetsliche = '',
CurrKartMitContainer = '',
CurrDragHintergrundT = '',
CurrKartGrenzeText = '',
CurrKartHinterGrund = '',
HiddenOrientation = '',
CurrDragOrientationV = '',
CurrDragOrientationH = '';
HiddenZiehlData  = '';
CurrKarte='',
CurrVarName='',
CurrFeildWidth='',
CurrFeildHeight='',
drag_answeroptioncount = 0,
CurrKartValue='';

tinymce.PluginManager.add('ifbq_dragables', function(editor, url) {
	
	editor.ui.registry.addButton('dragables', {
		cmd : 'mceShowDrag',
		text: 'Ablage',
		icon: 'table',
		image: tinymce.baseURL + '/plugins/ifbq_dragables/drag.png',
		id: 'dragable_antwortElement',
		class: 'dragables',
		tooltip:'Antwortelement',
		stateSelector:"img .dragables",
		onAction: ShowDragWindow
	});

	editor.on('Click', function (e) 
	{
		selectedNode = editor.selection.getNode();
		if (selectedNode.className && selectedNode.className.match('dragable') && selectedNode.className.match('dragable').length > 0)
		{
			var SelectedObj = selectedNode
			CurrFeildWidth = SelectedObj.clientWidth;
			CurrFeildHeight = SelectedObj.clientHeight;
			const attrAnzahlablage = SelectedObj.getAttribute('data-anzahl');
			CurrZusaetsliche =  getCssStyle(SelectedObj.getAttribute('style'),attrAnzahlablage);
			CurrVarName = SelectedObj.getAttribute('data-var');
			CurrKartZuShau = (SelectedObj.getAttribute('data-wert') == 'true') ? 'display:block;' : '';
			CurrDragIsUnEndlich = (SelectedObj.getAttribute('data-option') == 'true') ? 'checked' : '';
			CurrIstZieht = CurrKartZuShau== '' ? '' : 'goal_block';
			CurrSelectedGrenze = SelectedObj.getAttribute('data-grenze') !== undefined ? SelectedObj.getAttribute('data-grenze') : '';
			if (CurrSelectedGrenze.length)
				CurrSelectedGrenze = atob(CurrSelectedGrenze);
			CurrSelectedGrenzeList = CurrSelectedGrenze.split(',');

			if (typeof attrAnzahlablage !== 'undefined' && attrAnzahlablage !== false && attrAnzahlablage.length && attrAnzahlablage !== '1')
			{
				CurrDragAnzahlablage = SelectedObj.getAttribute('data-anzahl');
				CurrDragOrientationH = SelectedObj.classList.contains('horizontal') ? 'checked' : '';
				CurrDragOrientationV = SelectedObj.classList.contains('vertical') ? 'checked' : '';				
				HiddenOrientation = '';
			}
			else
			{
				CurrKartMitKarte = (SelectedObj.getAttribute('data-wert') == 'true') ? 'checked' : '';
				CurrKartMitContainer = (SelectedObj.getAttribute('data-wert') == 'true') ? 'checked' : '';
				HiddenZiehlData = CurrKartMitKarte == '' ? '' : 'display-none';
				HiddenContainerData = CurrKartMitContainer == 'checked' ? '' : 'display-none';
				const hatKarte = selectedNode.children.length;
				CurrDragHintergrundB = (!hatKarte || !selectedNode.children[0].classList.contains("bg-transparent")) ? 'checked' : '';
				CurrDragHintergrundT = (hatKarte && selectedNode.children[0].classList.contains("bg-transparent")) ? 'checked' : '';
				CurrKartValue = SelectedObj.children.length ? SelectedObj.children[0].getAttribute('data-value') : '';
				const antwortElementItem = SelectedObj.children.length ? SelectedObj.children[0]  : null; 
				const tBack = antwortElementItem && antwortElementItem.style['backgroundColor']
						? antwortElementItem.style['backgroundColor'] 
						: '#C2DEf3';
				CurrKartHinterGrund = rgbToHex(tBack);
			}
			
			CurrKarte = SelectedObj.children.length ? SelectedObj.children[0].innerHTML : '';
			GlobalSelection = selectedNode;
			editor.selection.select(selectedNode, true);
			ShowDragWindow();
			SetKartenColor()
		}
	});
	
	function componentToHex(c)
	{
		var hex = c.toString(16);
		return hex.length == 1 ? "0" + hex : hex;
	}
	
	const rgbToHex = (rgb) => 
	{
		rgb = rgb.toLowerCase();
		if(rgb.substring(0,3)!='rgb')
			return rgb

		const rgbArray = rgb.replace('rgb','').replace('(','').replace(')','').split(',')
		const hex ='#' + rgbArray.map(x => 
		{
			const hex = componentToHex(parseInt(x.trim()))
			return hex
		}).join('')

		return hex == "#NaN000000" ? '#C2DEf3' : hex
	}

	function ShowDragWindow() 
	{
		CurrKartGrenzeList = '';

		const tmporHtml = document.createElement("div");
		tmporHtml.innerHTML = editor.getContent();
		
		if(tmporHtml.getElementsByClassName('antwort-element').length)
		{
			Array.from(tmporHtml.getElementsByClassName('antwort-element')).forEach((element,idx) => {
				const value = element.getAttribute('data-value');
				const checkedItem = CurrSelectedGrenzeList.includes(value) || CurrSelectedGrenzeList.length < 1 ? 'checked' : '';
				CurrKartGrenzeList += '<li> <label for="chklst' + idx + '">' + value + '</label> <input name="chklst' + idx + '" type="checkbox" class="in-list-checkbox" id="chklst' + idx + '" value="' + value + '" ' + checkedItem + '></li>';
			});			
		}

		editor.windowManager.open({
			width: 570,
			height: 390,
			title: 'Variable Name ausfüllen',
			body: {
				type: 'panel', // The root body type - a Panel or TabPanel
				items: [ // A list of panel components
					{
						type: 'htmlpanel',
						height: 300,
						forced_root_block: false,
						name: '',
						label: '',
						html: '<div class="karte-info">' +
							'   <input type="hidden" id="alt_drag_var" name="alt_drag_var" value="' + CurrVarName + '">' +
							'   Variable <sup>*</sup>: <input class="tox-textfield" type="text" id="drag_var" name="drag_var" value="' + CurrVarName + '">' +
							'   <div class="tox-form__controls-h-stack">' +
							'       <div class="tox-form__group">' +
							'           Breite: <input class="tox-textfield" type="text" name="dWidth" id="dWidth" value="' + CurrFeildWidth + '">' +
							'       </div>' +
							'       <div class="tox-form__group">' +
							'           Höhe: <input class="tox-textfield" type="text" name="dHeight" id="dHeight" value="' + CurrFeildHeight + '">' +
							'       </div>' +
							'   </div>' +
							'   Zusätzlicher Stil (CSS): <input class="tox-textfield" type="text" name="zusaetsliche" id="zusaetsliche" value="' + CurrZusaetsliche + '">'+
							'   <div class="' + HiddenZiehlData + ' keine-karte">' +
							'       <div class="tox-form__group">' +
							'           Anzahl der Karten im Feld: <input class="tox-textfield" type="text" name="anzahlablage" id="anzahlablage" oninput ="return NumberClicked(event,this);" value="' + CurrDragAnzahlablage + '">' +
							'       </div>' +
							'       <div class="orientation keine-karte tox-form__group ' + HiddenOrientation + '">' +
							'           Erweiterung Richtung:<br/> <input type="radio" name="erweiterung" id="erweiterungH" ' + CurrDragOrientationH + '><label for="erweiterungH">&#8609; Waagerecht</label> <input type="radio" name="erweiterung" id="erweiterungV" ' + CurrDragOrientationV + '><label for="erweiterungV">&#8608; Senkrecht</label>' +
							'       </div>' +
							'   </div>' +
							'</div>' +
							'<div class="grenze-list-border"><div class="grenze-list ' + HiddenZiehlData + ' keine-karte" >' +
							'Akzeptierte Karten:' +
							CurrKartGrenzeText +
							'<ul class="in-list">' +
							CurrKartGrenzeList +
							'</ul>' +
							'</div></div>' +
							'<div class="karte">' +
							'   <p>Mit Karte: <input type="checkbox" name="mitkart" id="mitkart" ' + CurrKartMitKarte + '></p>' +
							'   <div id="dwert" style="display:none;height:280px;' + CurrKartZuShau + '">' +
							'	    <div style="height:280px;">' +
							'           <!--p>Mit einem Container: <input type="checkbox" name="mitcontainer" id="mitcontainer" ' + CurrKartMitContainer + '></p-->' +
							'           <p>Unendlich nutzbar: <input type="checkbox" name="unendlich" id="unendlich" ' + CurrDragIsUnEndlich + '></p>' +
							'           <p>Transparenter Kartenhintergrund: <input type="checkbox" onchange="SetKartenColor();" name="hitergrundfarbe" id="hitergrundfarbeT" ' + CurrDragHintergrundT + '></p>' +
							'           <p id="kartHinterGrundFarbeBlock" class="hidden">Kartenhintergrundfarbe: <input type="color" style="width: 60px;height: 30px;" onblur="SetKartenColor();" name="kartHinterGrund" id="kartHinterGrund" value="' + CurrKartHinterGrund + '"> <svg width="24" height="24"><path d="M3.5 12.5c.5.8 1.1 1.6 1.8 2.3 2 2 4.2 3.2 6.7 3.2s4.7-1.2 6.7-3.2a16.2 16.2 0 002.1-2.8 15.7 15.7 0 00-2.1-2.8c-2-2-4.2-3.2-6.7-3.2a9.3 9.3 0 00-6.7 3.2A16.2 16.2 0 003.2 12c0 .2.2.3.3.5zm-2.4-1l.7-1.2L4 7.8C6.2 5.4 8.9 4 12 4c3 0 5.8 1.4 8.1 3.8a18.2 18.2 0 012.8 3.7v1l-.7 1.2-2.1 2.5c-2.3 2.4-5 3.8-8.1 3.8-3 0-5.8-1.4-8.1-3.8a18.2 18.2 0 01-2.8-3.7 1 1 0 010-1zm12-3.3a2 2 0 102.7 2.6 4 4 0 11-2.6-2.6z" fill-rule="nonzero"></path></svg></p>' +
							'		    <p>Kartewert: <input type="text" name="karteval" id="karteval" value="' + CurrKartValue + '"></p>' +
							'		    <textarea id="werteditor"></textarea>' +
							'	    </div>' +
							'	</div>' +
							'</div>'
					}
				]
			},
			buttons: [
				{
					type: 'cancel',
					text: 'Abbrechen'
				},
				{
					type: 'submit',
					text: 'Ok',
					primary: true
				}
			],
			onSubmit: function (api) {

				
				if (document.getElementById('mitkart').checked && !document.getElementById('mitkart').value.length)
				{
					alert('Die Kartewert ist leer\n Bitte geben Sie sie eine Ergenzung');
					return false;
				}

				var dWidth = document.getElementById('dWidth').value;
				var dHeight = document.getElementById('dHeight').value;
				var zusaetsliche = document.getElementById('zusaetsliche').value;

				if (!dWidth || !dHeight || parseInt(dWidth) < 10 || parseInt(dHeight) < 10) {
					alert('Die Höhe und Breite sollen größer als 10!!');
					return false;
				}

				var dAltVarname = document.getElementById('alt_drag_var').value;
				var dVarname = document.getElementById('drag_var').value;

				//setConfigVarItems(dAltVarname,dVarname);

				const configDataGeaendert = new CustomEvent("dragConfigChanged", {
					detail: {
						dAltVarname,
						dVarname
					}
				});
				
				document.dispatchEvent(configDataGeaendert);
				
				var dVarStatus = document.getElementById('unendlich').checked;
				var dVarMit = document.getElementById('mitkart').checked;
				var dKarteval = document.getElementById('karteval').value;
				var dTtransparentColor = document.getElementById('kartHinterGrund').value;
				var dAnzahlablage = document.getElementById('anzahlablage').value;
				const dTtransparent = document.getElementById('hitergrundfarbeT').checked ? 'bg-transparent' : '';
				let dOriantation = 'inhaeltlich', dOrientirungH = '', dOrientirungV = '', dGrenzeItems = '';
				const grenze = [];

				const in_list_checkboxs = document.getElementsByClassName('in-list-checkbox');
				if(in_list_checkboxs.length)
				Array.from(in_list_checkboxs).forEach(element=> {
					if(element.checked)
						grenze.push(element.value)
				});

				dGrenzeItems = btoa(grenze.join());

				if (dAnzahlablage != '' && parseInt(dAnzahlablage) > 1) {

					if (document.getElementById('erweiterungV').checked) {
						dOriantation = 'vertical';
						dOrientirungV = 'min-'
						dOrientirungH = '';
					}
					else {
						dOriantation = 'horizontal';
						dOrientirungH = 'min-';
						dOrientirungV = ''
					}
				}

				var dContent = tinymce.get("werteditor").getContent();
				var dVarKart = (dVarMit) ? '<span style="width:' + dWidth + 'px;height:' + dHeight + 'px;background-color:' + dTtransparentColor + ';"  class="antwort-element ablagestart ' + dTtransparent + '" data-value="' + dKarteval + '" >' + dContent + '</span>' : '';
				//var BGImage =(dVarMit)? '': 'background-image:url(../bundles/concertopanel/files/dragpos2.png);';					
				dObject = '<span id="dragable_' + dVarname + '"  data-option="' + dVarStatus + '" data-anzahl="' + dAnzahlablage + '" data-grenze="' + dGrenzeItems + '" data-var="' + dVarname + '"  contentEditable="false" style="' + dOrientirungH + 'width:' + dWidth + 'px !important;' + dOrientirungV + 'height:' + dHeight + 'px !important;'+zusaetsliche+'" class="ablageziel ' + dOriantation + ' mceNonEditable dragable" data-wert="' + dVarMit + '">' + dVarKart + '</span>';
				if (GlobalSelection)
					GlobalSelection.outerHTML = dObject;
				else
					editor.selection.setContent(dObject);

				GlobalSelection = null;
				CurrDragIsUnEndlich = '';
				CurrSelectedGrenze = '';
				CurrSelectedGrenzeList = [];
				CurrDragAnzahlablage = '1';
				CurrDragOrientationH = '';
				CurrDragOrientationV = '';
				CurrDragHintergrundB = 'checked';
				CurrDragHintergrundT = '';
				HiddenOrientation = 'display-none';
				HiddenZiehlData = '';
				CurrIstZieht = 'goal_block';
				CurrKartZuShau = '';
				CurrKartMitKarte = '';
				CurrKartMitContainer = '';
				CurrKartGrenzeText = '';
				CurrKartGrenzeList = '';
				CurrKarte = '';
				CurrVarName = '';
				CurrFeildWidth = '';
				CurrFeildHeight = '';
				CurrZusaetsliche = '';
				CurrKartValue = '';
				CurrKartHinterGrund = '#C2DEf3';

				SelectedDragable++;
				tinymce.remove('textarea#werteditor');
				api.close();
			},
			onCancel: function () {
				tinymce.remove('textarea#werteditor');
				GlobalSelection = null;
				CurrDragIsUnEndlich = '';
				CurrSelectedGrenze = '';
				CurrSelectedGrenzeList = [];
				CurrDragAnzahlablage = '1';
				CurrDragOrientationH = '';
				CurrDragOrientationV = '';
				CurrDragHintergrundB = 'checked';
				CurrDragHintergrundT = '';
				CurrKartZuShau = '';
				CurrKartMitKarte = '';
				CurrKartMitContainer = '';
				CurrKartGrenzeText = '';
				CurrKartGrenzeList = '';
				CurrKarte = '';
				CurrVarName = '';
				CurrFeildWidth = '';
				CurrFeildHeight = '';
				CurrZusaetsliche = '';
				CurrKartValue = '';
				CurrKartHinterGrund = '#C2DEf3';
			},
			onClose: function () {
				tinymce.remove('textarea#werteditor');
				GlobalSelection = null;
				CurrDragIsUnEndlich = '';
				CurrSelectedGrenze = '';
				CurrSelectedGrenzeList = [];
				CurrDragAnzahlablage = '1';
				CurrDragOrientationH = '';
				CurrDragOrientationV = '';
				CurrDragHintergrundB = 'checked';
				CurrDragHintergrundT = '';
				CurrKartZuShau = '';
				CurrKartMitKarte = '';
				CurrKartMitContainer = '';
				CurrKartGrenzeText = '';
				CurrKartGrenzeList = '';
				CurrKarte = '';
				CurrVarName = '';
				CurrFeildWidth = '';
				CurrFeildHeight = '';
				CurrZusaetsliche = '';
				CurrKartValue = '';
				CurrKartHinterGrund = '#C2DEf3';
			}
		});
		
		tinymce.init({
			selector: 'textarea#werteditor',
			menubar: false,
			height:194,
			language: 'de',
			readonly: 0,
			forced_root_block: false,
			fontsize_formats: "8px 10px 12px 14px 18px 24px 36px",
			plugins: [
				'image', 'code', 
			],
			toolbar: 'styleselect | bold italic | alignleft aligncenter alignright alignjustify | bullist numlist outdent indent | image | code',
			setup: function (editor) {
				editor.on('init', function () {
					klineeditorexists = true;
					if (CurrKarte) {
						editor.setContent(CurrKarte);
						SetKartenColor();
					}
				});
			},
		});

		document.getElementById('mitkart').addEventListener("click",function (e)
		{
			if (this.checked)
			{
				document.getElementById('dwert').style.display = 'block';
				document.getElementById('anzahlablage').value = '1';
				Array.from(document.getElementsByClassName('keine-karte')).forEach((element,idx) => {
					element.style.display = 'none';
				});
			}
			else
			{
				document.getElementById('dwert').style.display = 'none';
				Array.from(document.getElementsByClassName('keine-karte')).forEach((element,idx) => {
					element.style.display = 'block';
				});
				if(document.getElementById('anzahlablage').value == '1')
				{
					Array.from(document.getElementsByClassName('orientation')).forEach((element,idx) => {
						element.style.display = 'none';
					});
				}
			}
		});


		document.getElementsByClassName('dragable').length
		&& 
		Array.from(document.getElementsByClassName('dragable')).forEach((item)=>
		{
			item.addEventListener("click",function (e) {
				SelectedDragable = this.getAttribute('data-value');
			});
		});
	}

});

function SetKartenColor()
{
	if (document.getElementById('hitergrundfarbeT').checked == true)
	{
		color = 'white';
		document.getElementById('kartHinterGrund').value = 'transparent';
		document.getElementById('kartHinterGrund').setAttribute('data-option','transparent');
		document.getElementById('kartHinterGrundFarbeBlock').classList.add('hidden');
	}
	else
	{
		if(document.getElementById('kartHinterGrund').getAttribute('data-option')=='transparent')
			document.getElementById('kartHinterGrund').value = '#C2DEf3';
		document.getElementById('kartHinterGrundFarbeBlock').classList.remove('hidden');
		color = document.getElementById('kartHinterGrund').value;//'#C2DEf3';
	}
	//alert(tinyMCE.getInstanceById('eComment'));
	var t = tinymce.get("werteditor");
	if(t)
		t.getBody().style.backgroundColor = color;
}

function getCssStyle(styles,attrAnzahlablage)
{
	const splitted = styles.split(';');
	let widthdthCss = false;

	const result = splitted.filter((item)=>{
		const doupleSplited = item.split(':');
		if(attrAnzahlablage !='1')
		{
			widthdthCss = doupleSplited[0].trim() != 'min-height' && doupleSplited[0].trim() != 'min-width' && doupleSplited[0] != ''
					&& doupleSplited[0].trim() != 'width' && doupleSplited[0].trim() != 'height' && doupleSplited[0] != ''
		}
		else
		{
			widthdthCss = doupleSplited[0].trim() != 'width' && doupleSplited[0].trim() != 'height' && doupleSplited[0] != ''
		}
		return widthdthCss && doupleSplited[0].trim() != 'background-color'
	})

	return result.length ? result.join(';')+';' : '';
}

function NumberClicked(event, obj)
{
	var charCode = (event.which) ? event.which : event.keyCode
	
	document.getElementsByClassName('orientation')[0].style.display = 'none';
	document.getElementsByClassName('grenze-list')[0].style.display = 'none';

	const kVal = document.getElementById('anzahlablage').value;
	const currVal = obj.value;

	if (parseInt(kVal) > 1) {
		document.getElementsByClassName('orientation')[0].style.display = 'block';
		document.getElementsByClassName('grenze-list')[0].style.display = 'block';
	}
	
	if (charCode > 31 && (charCode < 48 || charCode > 57))
	{
		return false;
	}
	else
	{
		return true;
	}	
}
